skills.card:
formatDate — Rewrite a date in a layout you choose, like DD/MM/YYYY or "D MMMM YYYY".
  needs: date: string, format: string
  e.g. "format 2026-11-14 as DD/MM/YYYY" → {"date":"2026-11-14","format":"DD/MM/YYYY"}

isWeekend — Say whether a date is a weekend or a working day.
  needs: date: string
  e.g. "is 2026-11-14 a weekend" → {"date":"2026-11-14"}

isoWeek — Number the week of the year a date sits in, and when that week begins.
  needs: date: string
  e.g. "what iso week is 2026-11-14" → {"date":"2026-11-14"}

timeAgo — Say how long ago a date was, or how far off it is, in plain words like "3 days ago".
  needs: date: string
  e.g. "how long ago was 2026-08-29" → {"date":"2026-08-29"}

spacedRepetitionSchedule — Work out the review dates for spaced repetition from a starting date.
  optional: date: string, intervals: array
  e.g. "when should I review this" → {"date":"2026-09-01"}

habitCompletionRate — Work out how many days you kept a habit, as a percentage of the days in the period.
  needs: dates: array, from: string, to: string
  e.g. "how often did I keep this habit" → {"dates":["2026-08-01","2026-08-02","2026-08-03"],"from":"2026-08-01","to":"2026-08-10"}

validateDate — Check whether a date actually exists on the calendar.
  needs: date: string
  e.g. "is 2026-02-29 a real date" → {"date":"2026-02-29"}
